import { fileURLToPath } from "node:url";
import type { NodePgDatabase } from "drizzle-orm/node-postgres";
import { migrate } from "drizzle-orm/node-postgres/migrator";

/**
 * The compiled migration SQL files (generated by `drizzle-kit generate`,
 * see `drizzle.config.ts`'s `out`). Resolved relative to this file so it
 * works both from `src/` (via `tsx`, dev) and from `dist/db/` (the
 * production build): the Dockerfile copies `drizzle/` to the image root
 * next to `dist/`, one level up from `dist/db/migrate.js`, mirroring
 * this file's own position one level up from `server/drizzle/` in the
 * source tree.
 */
const MIGRATIONS_FOLDER = fileURLToPath(new URL("../../drizzle", import.meta.url));

/**
 * Applies every pending migration in `drizzle/` against `db`, in order,
 * tracked in drizzle's own `__drizzle_migrations` journal table so an
 * already-applied migration is never re-run.
 *
 * Used at server startup (`index.ts`), before the HTTP server or
 * pg-boss start, so the process never serves a request or claims a job
 * against a schema that is missing a table or column it expects. A
 * failure here must abort startup rather than let the process come up
 * half-migrated — callers should let it throw and crash the process
 * (see `index.ts`'s `main().catch`).
 *
 * Kept separate from `drizzle-kit migrate` (the `db:migrate` npm
 * script, still used in development): drizzle-kit is a devDependency
 * and is not installed in the production image, so the migration this
 * function performs must go through `drizzle-orm`'s own runtime
 * migrator instead.
 */
export async function runMigrations(db: NodePgDatabase): Promise<void> {
  await migrate(db, { migrationsFolder: MIGRATIONS_FOLDER });
}
